92	    snd_vela_pcm_hw_params_malloc(&params);
93	    ret = snd_vela_pcm_hw_params_any(handle, params);
94	    if (ret < 0) {
95	        syslog(LOG_ERR, "[%s] hw_params_any fail %d\n", TAG, ret);
96	        goto err;
97	    }
98	
99	    snd_vela_pcm_hw_params_set_access(handle, params,
100	        SND_PCM_ACCESS_RW_INTERLEAVED);
101	    snd_vela_pcm_hw_params_set_format(handle, params, SND_PCM_FORMAT_S16_LE);
102	    snd_vela_pcm_hw_params_set_channels(handle, params, channels);
103	    snd_vela_pcm_hw_params_set_rate(handle, params, sample_rate, 0);
104	    snd_vela_pcm_hw_params_set_period_size(handle, params, period, 0);
105	    snd_vela_pcm_hw_params_set_buffer_size(handle, params, buffer);
106	
107	    ret = snd_vela_pcm_hw_params(handle, params);
108	    snd_vela_pcm_hw_params_free(params);
109	    params = NULL;
110	    if (ret < 0) {
111	        syslog(LOG_ERR, "[%s] hw_params fail %d\n", TAG, ret);
