115	    /* SW params：start_threshold=buffer（填满才启动），参考 dm_sound_open */
116	    {
117	        snd_pcm_sw_params_t* sw;
118	        snd_pcm_uframes_t boundary = 0;
119	
120	        snd_pcm_sw_params_alloca(&sw);
121	        snd_vela_pcm_sw_params_current(handle, sw);
122	        snd_vela_pcm_sw_params_get_boundary(sw, &boundary);
123	        snd_vela_pcm_sw_params_set_start_threshold(handle, sw, buffer);
124	        snd_vela_pcm_sw_params_set_stop_threshold(handle, sw, buffer);
125	        snd_vela_pcm_sw_params_set_silence_size(handle, sw, boundary);
126	        snd_vela_pcm_sw_params_set_avail_min(handle, sw, period);
127	        ret = snd_vela_pcm_sw_params(handle, sw);
128	        if (ret < 0) {
129	            syslog(LOG_ERR, "[%s] sw_params fail %d\n", TAG, ret);
130	            goto err;
131	        }
132	    }
133	
134	    audio_playback_t* pb = calloc(1, sizeof(*pb));
135	
136	    if (!pb) {
137	        goto err;
138	    }
139	
140	    pb->pcm = handle;
141	    pb->sample_rate = sample_rate;
142	    pb->channels = channels;
143	    pb->bits_per_sample = bits_per_sample;
144	    pb->stopped = 0;
145	
146	    syslog(LOG_INFO, "[%s] opened %s playback (%uHz %uch %ubit)\n",
147	        TAG, AGENT_PLAYBACK_CARD, sample_rate, channels, bits_per_sample);
