162	int audio_playback_write(audio_playback_t* pb,
163	    const void* buf, size_t len)
164	{
165	    if (!pb || !pb->pcm || !buf || len == 0) {
166	        return -EINVAL;
167	    }
168	
169	    /* AEC workaround: voice_channel_start() sets stopped to skip
170	     * remaining TTS chunks and prevent echo into the microphone. */
171	    if (pb->stopped) {
172	        return -ECANCELED;
173	    }
174	
175	    int frame_bytes = (int)pb->channels * ((int)pb->bits_per_sample / 8);
176	    snd_pcm_uframes_t frames = (snd_pcm_uframes_t)(len / (size_t)frame_bytes);
177	    snd_pcm_sframes_t n;
178	    int retries = 0;
179	
180	    if (frames == 0) {
181	        return 0;
182	    }
183	
184	    /* EAGAIN 短暂重试；EPIPE（xrun）prepare 恢复后重写 */
185	    for (;;) {
186	        n = snd_vela_pcm_writei(pb->pcm, buf, frames);
187	        if (n == -EAGAIN && retries < 10) {
188	            usleep(10 * 1000);
189	            retries++;
190	            continue;
191	        } else if (n == -EPIPE) {
192	            syslog(LOG_WARNING, "[%s] xrun, recovering\n", TAG);
193	            snd_vela_pcm_prepare(pb->pcm);
194	            if (retries < 10) {
195	                retries++;
196	                continue;
197	            }
198	        }
199	
200	        break;
201	    }
202	
203	    if (n < 0) {
204	        syslog(LOG_ERR, "[%s] writei fail %ld\n", TAG, (long)n);
205	        return (int)n;
206	    }
207	
208	    size_t written = (size_t)n * (size_t)frame_bytes;
209	
210	    pb->total_written += written;
211	    return (int)written;
212	}
