214	void audio_playback_stop(audio_playback_t* pb)
215	{
216	    if (pb) {
217	        pb->stopped = 1;
218	        /* drop 立即停流，让可能阻塞中的 writei() 返回，
219	         * 与旧 media_player_stop 语义一致，任意线程可调。 */
220	        if (pb->pcm) {
221	            snd_vela_pcm_drop(pb->pcm);
222	        }
223	    }
224	}
225	
226	void audio_playback_close(audio_playback_t* pb)
227	{
228	    if (!pb) {
229	        return;
230	    }
231	
232	    if (pb->pcm) {
233	        syslog(LOG_INFO, "[%s] closing (%zu bytes written)\n",
234	            TAG, pb->total_written);
235	        /* P103：正常播完（stopped=0）用 drain 等缓冲播完再关，防尾部
236	         * 截断（TTS 最后一块还在 8192 帧≈170ms buffer 里就被 drop 丢
237	         * 掉 → 播报"立马断掉"）；被打断（stopped=1）才 drop 立即停。 */
238	        if (pb->stopped) {
239	            snd_vela_pcm_drop(pb->pcm);
240	        } else {
241	            snd_vela_pcm_drain(pb->pcm);
242	        }
243	        snd_vela_pcm_close(pb->pcm);
244	        pb->pcm = NULL;
245	        syslog(LOG_INFO, "[%s] playback done\n", TAG);
246	    }
247	
248	    free(pb);
249	}

